			table_r6_a: "Sitze bei 50/50-Stimmen (Perzentil in der 1.010.000-Karten-Simulation)",
			table_r6_b: "46,1 % — p78 (normaler Bereich)",
			table_r6_c: "51,7 % — p99.99 (weniger als 100 von 1.010.000 erreichen das)",
